use super::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── A: the lane→row map is a memory-access decision that doubles
        // as a reduction-shape decision — permute it and the butterfly's
        // leading steps become register work, IF the tree is preserved. ──
        KernelRule {
            rule_id: "lane-permuted-column-reduce-same-butterfly-tree-bit-identity".to_string(),
            gpu_concept: "MECHANISM (warp column reduction; category A — memory access/lane-map): the incumbent eager GDN kernel gives each warp 4 columns of the 128-wide state with lane L holding rows r*32 + L of each, so every column's dot ends in a full 5-step warp butterfly (verbatim: 'In gated_delta_net_cuda a warp owns 4 columns and lane L holds rows r*32 + L of each; a column's dot products end in warp_reduce_sum (xor 16, 8, 4, 2, 1), 40 shuffles per token.') — 40 shuffles per token at 4 columns x 2 reductions x 5 steps. The L8 arm PERMUTES THE LANE-TO-ROW MAP instead of changing the arithmetic ('Here the 8 lanes of group grp = lane / 8 own column col + grp, and lane n = lane % 8 holds the rows of the old lanes n + 8m (m = 0..3).'): each lane forms the old lanes' 4-row partial chains in registers and folds them in the butterfly's own pairing order — 'It forms the old lanes' partial sums with the same r-ordered chains, folds them as the first two butterfly steps do, (x_n + x_n+16) + (x_n+8 + x_n+24), and finishes with xor 4, 2, 1 inside the group: the same leaves in the same tree, so every column value, state element, attention output, lazy record (inputs, base and the old per-warp checksum) and snapshot is bit-identical to gated_delta_net_cuda. 6 shuffles per token.' The register fold IS the first two butterfly steps in code ('float x = __fadd_rn(__fadd_rn(p[0], p[2]), __fadd_rn(p[1], p[3]));' — kernel.cuh:530), the remaining three steps run inside the 8-lane group. BIT-IDENTITY IS LOAD-BEARING, not cosmetic: the lazy-rollback record's per-warp checksum is computed over the stored base in the OLD layout order ('// old-layout checksum of the 4 columns of this warp, read back from base (gdn_lazy_store_base's order)' — kernel.cuh:515), so both arms must produce identical bytes or cross-arm records fail validation. Admission is a prefill token gate ('#define GDN_L8_MIN_TOKENS 17  // ubatches of at least this many tokens use it (prefill)' — kernel.cuh:510) with env kill-switch GGML_CUDA_GDN_L8=0. DECISION CONTENT: (a) a lane remap that only permutes WHICH lane holds which row can fold leading butterfly steps into register arithmetic, provided the fold reproduces the butterfly's exact pairing order — the tree must be preserved leaf-for-leaf, never approximated; (b) bit-identity is a contract, not a nicety, whenever a persistent checksum or committed record is produced by both arms — the checksum's read order pins the layout agreement; (c) the shuffle budget is the gate: 40 -> 6 shuffles/token pays at prefill token loops, so admission is a measured minimum token count, never unconditional; (d) ship the arm behind an env kill-switch so the incumbent is one variable away. REGIME: eager per-column warp reductions over wide states (S_v=128, 4 columns/warp, 4-row shards) at prefill token loops. ANTI-REGIME: decode-sized ubatches (the shuffle count is not the binding cost); chunked/MMA prefill kernels (register-resident-scan-state owns that substrate); remaps whose fold cannot reproduce the butterfly pairing exactly. KINSHIP (do not double-count): register-resident-scan-state-one-kernel-layer-pass (B234) is the chunked-MMA prefill with an argmax-stability contract — THIS is the EAGER path with a tree-preservation contract; an instance of recurrence-prefill-exact-restructure-before-reformulation (B114 — restructure the exact computation before reformulating) with a NEW mechanism (the tree-preserving lane permutation); distinct from gdn-transition-replay-log-commit-many (B182 — journal/commit, not reduction shape). NOVEL (grep 'lane.?permut|butterfly.{0,25}(tree|preserve)|__fadd_rn.{0,40}__fadd_rn' over both corpora at claim: the only hits are entries_gpu_09's load-instruction lane-permutation comment and entries_gpu_02's reduction-depth comment — different axes; ZERO owners of the mechanism). NotBenchable here (no GB10/CUDA host in this corpus's served paths; the 40 -> 6 shuffle delta is source-stated and the bit-identity is a contract — CPU-testable oracle: fold-tree equality). Source: Layr-Labs/cudafast-bonsai2-9b-engine @ 36c9536, MIT — llama.cpp/ggml/src/ggml-cuda/gated_delta_net_kernel.cuh:498-536. Batch 251 / Plan 255 / Research 284.".to_string(),
            ref_shape: "// naive: a warp owns 4 columns; lane L holds rows r*32 + L of each\n// and every column's dot ends in a full 5-step warp butterfly\n// (xor 16, 8, 4, 2, 1) — 40 shuffles per token at\n// 4 columns x 2 reductions x 5 steps.\n\n// lane L's r-ordered partial over the 128-row column (state*k\n// products pre-materialized as `a`)\nfn lane_partials(a: &[f32; 128]) -> [f32; 32] {\n    let mut p = [0.0f32; 32];\n    for chunk in a.chunks_exact(32) {\n        for (l, x) in chunk.iter().enumerate() {\n            p[l] += *x; // the chain over r in order, per lane\n        }\n    }\n    p\n}\n\nfn butterfly_total(v: &[f32; 32]) -> f32 {\n    let mut cur = *v;\n    for offset in [16usize, 8, 4, 2, 1] {\n        let old = cur;\n        for i in 0..32 {\n            cur[i] = old[i] + old[i ^ offset]; // __shfl_xor_sync + add\n        }\n    }\n    cur[0]\n}\n\nfn column_dot_naive(a: &[f32; 128]) -> f32 {\n    butterfly_total(&lane_partials(a)) // 5 shuffles per reduction, per column\n}\n".to_string(),
            opt_pattern: "// optimized: the lane→row map permuted — lane n of the group owns\n// the rows of old lanes n + 8m (m = 0..3). The four partials are\n// register chains in the same r order; the fold (p0+p2)+(p1+p3) IS\n// the first two butterfly steps; xor 4/2/1 inside the 8-lane group\n// finishes the SAME tree. 6 shuffles per token.\n\nfn lane_partials(a: &[f32; 128]) -> [f32; 32] {\n    let mut p = [0.0f32; 32];\n    for chunk in a.chunks_exact(32) {\n        for (l, x) in chunk.iter().enumerate() {\n            p[l] += *x;\n        }\n    }\n    p\n}\n\nfn butterfly_total(v: &[f32; 32]) -> f32 {\n    let mut cur = *v;\n    for offset in [16usize, 8, 4, 2, 1] {\n        let old = cur;\n        for i in 0..32 {\n            cur[i] = old[i] + old[i ^ offset];\n        }\n    }\n    cur[0]\n}\n\nfn column_dot_naive(a: &[f32; 128]) -> f32 {\n    butterfly_total(&lane_partials(a)) // the incumbent, as the oracle\n}\n\nfn group_fold_totals(a: &[f32; 128]) -> [f32; 4] {\n    let mut totals = [0.0f32; 4];\n    for g in 0..4 {\n        let mut s = [0.0f32; 8]; // lane n's folded value\n        for n in 0..8 {\n            let mut p = [0.0f32; 4];\n            for m in 0..4 {\n                let mut chain = 0.0f32;\n                for r in 0..4 {\n                    chain += a[r * 32 + n + 8 * m]; // the same r-ordered chain\n                }\n                p[m] = chain; // old lane n + 8m's partial\n            }\n            // (x_n + x_n+16) + (x_n+8 + x_n+24): the first two butterfly steps\n            s[n] = (p[0] + p[2]) + (p[1] + p[3]);\n        }\n        for offset in [4usize, 2, 1] {\n            let old = s;\n            for i in 0..8 {\n                s[i] = old[i] + old[i ^ offset]; // xor 4, 2, 1 inside the group\n            }\n        }\n        totals[g] = s[0];\n    }\n    totals\n}\n\nfn column_dot_l8(a: &[f32; 128]) -> f32 {\n    group_fold_totals(a)[0] // every group's total: the same tree, same bits\n}\n\n#[test]\nfn the_permuted_lane_map_reproduces_the_butterfly_tree_bitwise() {\n    // deterministic input with wild magnitude spread so a wrong\n    // association order cannot hide\n    let mut a = [0.0f32; 128];\n    let mut x: u32 = 0x1234_5678;\n    for i in 0..128 {\n        x = x.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);\n        a[i] = ((x >> 8) as f32) * 1.0e-6; // pseudo-random, magnitudes ~16\n    }\n    a[0] = 1.0e8;\n    a[1] = 1.0;\n    a[2] = -1.0e8; // association-sensitive values in old lanes 0..2\n    let naive = column_dot_naive(&a);\n    assert_eq!(column_dot_l8(&a).to_bits(), naive.to_bits(), \"the fold tree must be the butterfly tree, bit for bit\");\n    for g in 1..4 {\n        assert_eq!(group_fold_totals(&a)[g].to_bits(), naive.to_bits(), \"all four groups reduce the same tree\");\n    }\n    // sensitivity check: a WRONG pairing ((p0+p1)+(p2+p3)) must be\n    // detectable on this input — otherwise the test proves nothing\n    let mut wrong = [0.0f32; 8];\n    for n in 0..8 {\n        let mut p = [0.0f32; 4];\n        for m in 0..4 {\n            let mut c = 0.0f32;\n            for r in 0..4 {\n                c += a[r * 32 + n + 8 * m];\n            }\n            p[m] = c;\n        }\n        wrong[n] = (p[0] + p[1]) + (p[2] + p[3]); // the WRONG pairing\n    }\n    for offset in [4usize, 2, 1] {\n        let old = wrong;\n        for i in 0..8 {\n            wrong[i] = old[i] + old[i ^ offset];\n        }\n    }\n    assert_ne!(wrong[0].to_bits(), naive.to_bits(), \"a wrong fold must not pass this oracle\");\n}\n".to_string(),
        },
        // ── G: rollback across ubatches — journal the small inputs, gate
        // every read, replay bit-for-bit, and fall back to the eager slot
        // on ANY mismatch. ──
        KernelRule {
            rule_id: "lazy-rollback-journaled-window-replay-replaces-eager-state-snapshots".to_string(),
            gpu_concept: "MECHANISM (recurrent-state rollback across ubatches; category G — state/rollback traffic): the eager scheme writes a FULL state snapshot per rollback slot — verbatim: 'The eager scheme writes the full state after each of the last K tokens into rollback slots 0..K-1 (2 MiB per slot for 32 heads x 128 x 128 f32), although the next ubatch reads at most one of them.' The lazy scheme JOURNALS instead ('The lazy scheme writes the final state to slot 0, the state at the start of the rollback window to slot 1, and each block's per-token inputs to slot 2 + blockIdx.z.') — final state + window base + per-token RAW inputs (k, v, g, beta), a record of header + W token strides, not K state copies. On rollback the state is REBUILT ('the block reloads slot 1 and replays the first W - r window tokens with the same per-column arithmetic as the main loop, which reproduces the eager snapshot bit for bit.') and EVERY read is GATED ('A record that does not match (magic, window, per-warp checksum of the stored base) falls back to reading slot r as written by the eager scheme.') — the grid budget rides the same gate ('lazy = lazy && state_slot_stride > 0 && 2 + (int) gridDim.z <= K;' — kernel.cuh:304). The magic word is the COMMIT POINT: publication order is payload, per-warp checksum words, __syncthreads, window/flag, '__threadfence_block();' then 'hdr[0] = GDN_LAZY_MAGIC;' (kernel.cuh:163-164) — a reader that sees the magic sees a complete record. The checksum read-back is itself gated ('if (gdn_lazy_warp_hash<warp_size>(h) != hdr[4 + threadIdx.y]) {' / 'return false;  // slot 1 no longer holds this record's base' — kernel.cuh:198-199): the hash seeds from the FNV-1a offset basis (0x811c9dc5) and mixes with the hash_combine form, per warp lane. The verify-sized face: a ubatch whose window is ALL its tokens skips the final-state store entirely — 'its record says so (GDN_LAZY_NOFINAL) and it marks slot 0 (GDN_LAZY_SLOT0_MARK0/1 in the first two elements of each warp's first column, two finite values, so that the zeroing SCALE of a fresh cell still gives zeros)' (kernel.cuh:64-66) — the mark constants are finite floats (~1.0e-20, ~-5.7e-22) chosen so downstream scale arithmetic stays numerically inert, and ANY other write of slot 0 (a final-state store, the eager snapshots, a zeroing of the row) removes the mark bit-naturally by overwriting it. DECISION CONTENT: (a) K full-state snapshots (2 MiB/slot) where the consumer reads at most one is a write-amplification defect — journal the small per-token inputs and rebuild on demand; (b) the replay must reuse the main loop's per-column arithmetic verbatim — bit-for-bit is the acceptance bar, because the eager fallback must be indistinguishable from the replay; (c) every record read is gated on magic + window bounds + grid budget + per-warp base checksum, with the EAGER-SLOT FALLBACK as the only failure path — a torn or stale record (slot 1 overwritten by a later ubatch) degrades to the eager read, never to wrong data; (d) publication is ordered and the magic is LAST — the commit point a reader keys on; (e) verify-sized arms can skip the final state when the window covers every token, marking slot 0 with FINITE sentinel floats plus the NOFINAL header flag so slot-0 readers replay from slot 1. REGIME: recurrent-state caches with multi-slot rollback (keep_rs) across ubatches where the per-slot snapshot (S_v x S_v per head) dwarfs the per-token inputs; single-sequence rows. ANTI-REGIME: K == 1 (no window to journal); multi-sequence rows (the record addressing assumes n_seqs == 1 at the journal sites); consumers that read MOST slots (per-slot replay cost exceeds the snapshot writes saved). KINSHIP (do not double-count): gdn-transition-replay-log-commit-many (B182) journals transition ingredients to COMMIT the accepted tokens post-selection — THIS rebuilds a PRE-ROLLBACK state across ubatches with checksum + eager fallback; the full-acceptance-state-store face (entries_gpu_60) conditionally stores a verify's final state keyed on a host predictor — different stored quantity and trigger; write-before-read checkpoint families own checkpoint SETS — THIS owns the journal/replay of one row's window. NOVEL (grep 'lazy.?rollback|journaled.{0,25}window|NOFINAL|SLOT0_MARK' over both corpora at claim: broad 'replay' vocabulary routes to the speculative-verify families; ZERO owners of the journaled-window rollback with the eager-slot fallback). NotBenchable here (no CUDA host in this corpus's served paths; the 2 MiB/slot vs per-token-record delta is count-stated and the bit-for-bit replay is a contract — full ladder CPU-portable). Source: Layr-Labs/cudafast-bonsai2-9b-engine @ 36c9536, MIT — llama.cpp/ggml/src/ggml-cuda/gated_delta_net_kernel.cuh:52-115, 153-166, 168-229, 304 + gated_delta_net.cu:180-193. Batch 251 / Plan 255 / Research 284.".to_string(),
            ref_shape: "// naive (eager): the full state after each of the last K tokens is\n// written to its own rollback slot; the next ubatch reads one slot\n// and pays K full-state writes per ubatch for it.\n\nconst SV: usize = 8; // S_v, shrunk for the mirror\n\nfn step(s: &mut [f32; SV], g: f32) {\n    for v in s.iter_mut() {\n        *v = *v * 0.5 + g; // the recurrence\n    }\n}\n\nfn eager_run(tokens: &[f32], state0: &[f32; SV], k: usize) -> Vec<[f32; SV]> {\n    let mut s = *state0;\n    let mut slots: Vec<[f32; SV]> = Vec::new();\n    for (t, g) in tokens.iter().enumerate() {\n        step(&mut s, *g);\n        let target = tokens.len() - 1 - t; // slot 0 = most recent\n        if target < k {\n            if slots.len() <= target {\n                slots.resize(target + 1, [0.0; SV]);\n            }\n            slots[target] = s; // a FULL-state snapshot per token\n        }\n    }\n    slots\n}\n\nfn eager_rollback(slots: &[[f32; SV]], r: usize) -> [f32; SV] {\n    slots[r] // read slot r as written\n}\n".to_string(),
            opt_pattern: "// optimized (lazy): journal the window base ONCE + the per-token\n// RAW inputs; on rollback validate (magic, window, budget, checksum)\n// and replay W - r tokens with the SAME arithmetic; any mismatch\n// falls back to the eager slot. The magic is published LAST — it is\n// the commit point.\n\nconst SV: usize = 8;\nconst MAGIC: u32 = 0x4744_314c; // \"GD1L\"\nconst NOFINAL: u32 = 0x4e4f_4631; // hdr[2]: slot 0 holds no final state\nconst MARK0: u32 = 0x1e3d_5b79; // ~1.0e-20 — finite, so a zeroing SCALE\nconst MARK1: u32 = 0x9c2b_4f8d; // ~-5.7e-22 — of a fresh cell still gives zeros\n\n#[derive(Clone)]\nstruct Record {\n    hdr: [u32; 8],   // magic, W, final flag, reserved, per-lane checksum x4\n    base: [f32; SV], // the state at the window start (slot 1)\n    toks: Vec<f32>,  // the RAW per-token inputs\n}\n\nfn mix(h: u32, x: u32) -> u32 {\n    h ^ x.wrapping_add(0x9e37_79b9).wrapping_add(h << 6).wrapping_add(h >> 2)\n}\n\nfn checksum(base: &[f32; SV], lane: usize) -> u32 {\n    let mut h = 0x811c_9dc5u32 ^ (lane as u32); // the FNV-1a offset basis seed\n    for v in base {\n        h = mix(h, v.to_bits());\n    }\n    h\n}\n\nfn step(s: &mut [f32; SV], g: f32) {\n    for v in s.iter_mut() {\n        *v = *v * 0.5 + g; // the SAME arithmetic everywhere\n    }\n}\n\nfn eager_run(tokens: &[f32], state0: &[f32; SV], k: usize) -> Vec<[f32; SV]> {\n    let mut s = *state0;\n    let mut slots: Vec<[f32; SV]> = Vec::new();\n    for (t, g) in tokens.iter().enumerate() {\n        step(&mut s, *g);\n        let target = tokens.len() - 1 - t;\n        if target < k {\n            if slots.len() <= target {\n                slots.resize(target + 1, [0.0; SV]);\n            }\n            slots[target] = s;\n        }\n    }\n    slots\n}\n\nfn lazy_journal(tokens: &[f32], state0: &[f32; SV], k: usize) -> Record {\n    let mut s = *state0;\n    let w = tokens.len().min(k);\n    let t0 = tokens.len() - w;\n    let mut rec = Record { hdr: [0; 8], base: [0.0; SV], toks: Vec::with_capacity(w) };\n    for (t, g) in tokens.iter().enumerate() {\n        if t == t0 {\n            rec.base = s; // the window base, journaled once\n        }\n        if t >= t0 {\n            rec.toks.push(*g); // the RAW inputs — no state snapshot\n        }\n        step(&mut s, *g);\n        // NOT written: the per-token full-state snapshots. That is the point.\n    }\n    rec.hdr[1] = w as u32;\n    rec.hdr[2] = 0; // the final state DOES live in slot 0 in this posture\n    for lane in 0..4 {\n        rec.hdr[4 + lane] = checksum(&rec.base, lane);\n    }\n    rec.hdr[0] = MAGIC; // publish LAST: the magic is the commit point\n    rec\n}\n\nfn replay_or_fallback(\n    rec: &Record,\n    eager_slots: &[[f32; SV]],\n    r: usize,\n    k: usize,\n    budget_ok: bool,\n) -> ([f32; SV], bool) {\n    let w = rec.hdr[1] as usize;\n    let ok = budget_ok\n        && rec.hdr[0] == MAGIC\n        && w >= 1\n        && w <= k\n        && r <= w\n        && rec.hdr[4] == checksum(&rec.base, 0); // the record's lane-0 checksum\n    if !ok {\n        return (eager_slots[r], false); // the EAGER-SLOT FALLBACK — never wrong data\n    }\n    let mut s = rec.base;\n    for g in &rec.toks[0..w - r] {\n        step(&mut s, *g); // the FIRST W - r window tokens, the same per-column arithmetic\n    }\n    (s, true)\n}\n\n#[test]\nfn the_replay_is_the_eager_snapshot_bit_for_bit_and_bad_records_fall_back() {\n    const K: usize = 4;\n    let tokens: Vec<f32> = (0..6).map(|i| 0.1 * (i as f32 + 1.0)).collect();\n    let state0 = [0.25f32; SV];\n\n    let slots = eager_run(&tokens, &state0, K); // the eager reference\n    let rec = lazy_journal(&tokens, &state0, K); // journals base + inputs only\n    assert_eq!(rec.hdr[0], MAGIC, \"the magic is published last, as the commit point\");\n\n    for r in 0..slots.len() {\n        let (got, replayed) = replay_or_fallback(&rec, &slots, r, K, true);\n        assert!(replayed, \"a valid record replays slot {r}\");\n        assert_eq!(got, slots[r], \"the replay must be the eager snapshot, bit for bit\");\n    }\n\n    // a base that no longer matches its checksum takes the fallback\n    let mut torn = rec.clone();\n    torn.base[0] += 1.0;\n    let (got, replayed) = replay_or_fallback(&torn, &slots, 1, K, true);\n    assert!(!replayed, \"a checksum mismatch must take the eager-slot fallback\");\n    assert_eq!(got, slots[1], \"the fallback serves the eager slot's bits\");\n\n    // an unpublished record (the magic not yet written) refuses too\n    let mut unpublished = rec.clone();\n    unpublished.hdr[0] = 0;\n    assert!(!replay_or_fallback(&unpublished, &slots, 1, K, true).1);\n\n    // the grid budget gate: 2 + gridDim.z <= K\n    assert!(!replay_or_fallback(&rec, &slots, 1, K, false).1);\n\n    // the verify-sized marks: finite floats, so a fresh-cell zeroing\n    // scale still yields zeros — and the NOFINAL header flag exists\n    let m0 = f32::from_bits(MARK0);\n    let m1 = f32::from_bits(MARK1);\n    assert!(m0.is_finite() && m1.is_finite());\n    assert_eq!((0.0f32 * m0).to_bits(), 0.0f32.to_bits(), \"scale 0 x mark stays zero\");\n    let _ = NOFINAL;\n}\n".to_string(),
        },
        // ── C: a deferred op whose destination a consumer fully overwrites
        // is dead work — fold its expression into the load, elide the
        // launch, refuse every other posture loudly. ──
        KernelRule {
            rule_id: "dead-destination-scale-elided-consumer-applies-on-load".to_string(),
            gpu_concept: "MECHANISM (dead-work elision; category C — dead-work elision): a deferred zeroing SCALE whose destination row is the SAME row the GDN kernel is about to overwrite is dead work — the launcher detects the alias and the kernel applies the scale's expression during the state load (verbatim: 'a deferred zeroing SCALE of a cache row: gated_delta_net_l8_cuda applies it on load when it also overwrites that row (slot 0 of the cell it writes, n_seqs == 1); otherwise the SCALE runs now, before the kernel reads the row' — gated_delta_net.cu:267-268). The admission guard is POINTER + BYTE SIZE + sequence count ('if (l8 && cache != nullptr && n_seqs == 1 && (const float *) zero_node->data == state_d &&' / 'ggml_nbytes(zero_node) == (size_t) S_v * S_v * H * sizeof(float)) {' — gated_delta_net.cu:278-279); the kernel derives the same alias from its own pointers ('const bool zeroed = zero_row != nullptr && curr_state + state_row == zero_row;' — kernel.cuh:569) and folds the expression into the load ('s[m*4 + r] = zeroed ? zero_scale * x + zero_bias : x;  // scale_f32's expression' — kernel.cuh:630) — the fold is scale_f32's own expression, so the result is bit-identical to running the scale first. The refusals are loud: every non-eligible arm asserts the scale was NOT passed ('GGML_ASSERT(zero[0] == nullptr);' — gated_delta_net.cu:90), and the lazy-replay path is refused when the row is to be scaled ('if (lazy && !zeroed) {' — kernel.cuh:578 — the scale's write would destroy the record's slot-0 semantics, so a scaled row takes the eager read with the on-load fold, never the replay). DECISION CONTENT: (a) a deferred elementwise op whose destination is FULLY overwritten by a consumer kernel is dead work — fold its expression into the consumer's load and elide the launch; (b) admission is a runtime POINTER + BYTE-SIZE alias guard plus the shape condition (n_seqs == 1) — never op-graph order alone, because the alias is a runtime address fact; (c) the folded expression must be the producer's expression verbatim (zero_scale * x + zero_bias, scale_f32's own form): bit-identity is the contract, a mathematically-equal rewrite is not; (d) every other posture refuses loudly or falls back — non-eligible arms hard-assert, the lazy-replay path skips the record when the row would be scaled, and the fallback runs the scale eagerly BEFORE the kernel reads. REGIME: deferred zeroing/first-touch scaling of a state row immediately consumed and overwritten by one kernel at n_seqs == 1. ANTI-REGIME: multi-sequence rows (the guard refuses); scales whose destination the consumer only partially overwrites; consumers that read the row BEFORE writing it (the scale must run first — the fallback); chains of deferred ops (only the single aliasing scale folds). KINSHIP (do not double-count): constant-scale-folded-into-upload-copy and per-row-scale-folded-into-rhs-staging-tile fold scales into COPIES/staging that SURVIVE as the operand — THIS folds into a write that makes the producer dead; inplace-grad-accumulate-deferred-postscale DEFERS a scale to preserve accumulation — the opposite direction; graph dead-node elimination owns statically-dead nodes — THIS owns runtime-alias dead work between two live nodes. NOVEL (grep 'zero.?scale|dead.?destination|scale.{0,20}elided|applies.{0,12}on.?load' over both corpora at claim: the 'zero scale' hits are the LoRA zero-alpha rule (min-rank-inert-adapter-zero-alpha) — a different meaning entirely; ZERO owners of the dead-destination elision). NotBenchable here (no CUDA host in this corpus's served paths; the elided launch is count-stated — CPU-testable: on-load fold == eager scale-then-read, bitwise). Source: Layr-Labs/cudafast-bonsai2-9b-engine @ 36c9536, MIT — llama.cpp/ggml/src/ggml-cuda/gated_delta_net.cu:267-288, 90 + gated_delta_net_kernel.cuh:568-578, 624-633. Batch 251 / Plan 255 / Research 284.".to_string(),
            ref_shape: "// naive: the deferred zeroing SCALE runs as its own launch before\n// the consumer kernel reads the row — a full pass over a row the\n// consumer is about to overwrite anyway.\n\nfn scale_row_eager(row: &mut [f32], scale: f32, bias: f32) {\n    for x in row.iter_mut() {\n        *x = scale * *x + bias; // scale_f32's expression, its own launch\n    }\n}\n\nfn consume_row_naive(row: &[f32]) -> f32 {\n    row.iter().sum() // the GDN kernel reads the row it will overwrite\n}\n".to_string(),
            opt_pattern: "// optimized: the launcher's alias guard (pointer + byte size +\n// n_seqs) detects that the scale's destination IS the row the kernel\n// overwrites; the kernel applies the scale's expression ON LOAD — the\n// scale launch is dead work and is elided. Any guard mismatch runs\n// the scale eagerly first; the lazy-replay path refuses a scaled row.\n\nfn scale_row_eager(row: &mut [f32], scale: f32, bias: f32) {\n    for x in row.iter_mut() {\n        *x = scale * *x + bias; // scale_f32's expression, its own launch\n    }\n}\n\nfn consume_row_naive(row: &[f32]) -> f32 {\n    row.iter().sum()\n}\n\n/// `scaled == true` models the alias guard passing: the consumer\n/// applies the scale's expression during the load.\nfn consume_row_with_dead_scale(row: &[f32], scaled: bool, scale: f32, bias: f32) -> f32 {\n    // `scaled == false` models the guard refusing: the caller ran the\n    // eager scale first (the fallback), so the load applies nothing\n    row.iter().map(|x| if scaled { scale * x + bias } else { *x }).sum()\n}\n\n/// kernel.cuh:578 — 'if (lazy && !zeroed)': a scaled row never takes\n/// the lazy-replay path (the scale's write destroys the record's\n/// slot-0 semantics); it takes the eager read with the fold.\nfn lazy_replay_allows_zeroed(zeroed: bool) -> bool {\n    !zeroed\n}\n\n#[test]\nfn the_on_load_expression_is_the_scale_launch_bitwise() {\n    let mut row = [1.0f32, -2.5, 3.25, 1.0e8, -1.0e8, 0.0];\n    let (scale, bias) = (0.5f32, 0.125);\n\n    // the eager posture: the scale launches, then the consumer reads\n    let mut eager = row;\n    scale_row_eager(&mut eager, scale, bias);\n    let want = consume_row_naive(&eager);\n\n    // the elided posture: the consumer applies the expression on load\n    let got = consume_row_with_dead_scale(&row, true, scale, bias);\n    assert_eq!(got.to_bits(), want.to_bits(), \"the on-load fold is scale_f32's expression, bit for bit\");\n\n    // the guard-refused posture: the eager scale runs first, the load\n    // applies nothing — same bits, different path\n    scale_row_eager(&mut row, scale, bias);\n    let fell_back = consume_row_with_dead_scale(&row, false, scale, bias);\n    assert_eq!(fell_back.to_bits(), want.to_bits());\n\n    // the lazy-replay refusal\n    assert!(!lazy_replay_allows_zeroed(true), \"a scaled row must not take the replay path\");\n    assert!(lazy_replay_allows_zeroed(false));\n}\n".to_string(),
        },
        // ── B: cross-warp transcendental redundancy — one precompute pass
        // at a measured threshold, template-paired so double activation
        // cannot compile. ──
        KernelRule {
            rule_id: "gate-activation-precompute-pass-token-threshold-gated".to_string(),
            gpu_concept: "MECHANISM (cross-warp redundancy; category B — compute): in the eager GDN every column-warp recomputes the same per-(token, head) transcendental gates — four warps per head block, four identical exp/softplus/sigmoid chains per token. Two precompute passes hoist the redundancy at measured token thresholds: exp(g) once per (token, head) — verbatim: 'GB10 long-prompt path: exp(g) once per (token, head) instead of once per column-warp. Only for activated gates; with raw gates (#165) the activation happens inside the kernel.' — admitted at 'if (!kda && !raw && S_v == 128 && n_tokens >= 32 &&' (gated_delta_net.cu:233; the cc gate continues the line); and the raw-gate activation (softplus overflow branch + sigmoid producing g AND beta together) at 'if (raw && keep_rs && l8_enabled && S_v == 128 && n_tokens >= GDN_L8_RAW_PRE_MIN_TOKENS &&' with '#define GDN_L8_RAW_PRE_MIN_TOKENS 64  // raw gates are activated in a separate pass from this many tokens on' (kernel.cuh:511). The pass is documented as the KERNEL'S OWN EXPRESSIONS: 'GB10 prefill with raw gates: beta and g activated once per (token, head) with gated_delta_net_cuda's RAW expressions (the per-token values it would form in every column warp), ready for G_PRECOMPUTED.' (kernel.cuh:30-31). The kernel consumes the precomputed values behind a template flag — '// G_PRECOMPUTED: g already holds exp(g) (GB10 long-prompt path); only used with RAW == false.' (kernel.cuh:233) — and the pairing is a COMPILE-TIME law: 'static_assert(!(RAW && G_PRECOMPUTED), \"exp(g) precompute is only defined for activated gates\");' (kernel.cuh:357) forbids double activation (raw gates pre-activated AND exp applied to an already-activated value cannot compile). DECISION CONTENT: (a) cross-warp transcendental redundancy (N column-warps re-deriving one per-(token, head) gate) is a prefill-class cost — hoist to one elementwise pass at a token threshold; (b) the threshold is per-activation and measured: exp(g) at >= 32 tokens, the full raw activation (softplus branch + sigmoid, g AND beta together) at >= 64 — short ubatches keep the fused in-kernel form; (c) pair the template flags so double activation is a COMPILE error, not a runtime bug — static_assert(!(RAW && G_PRECOMPUTED)); (d) the pass reproduces the kernel's branch structure VERBATIM (the softplus overflow cut included) — same bits, or the precomputed path is a numerics change wearing an optimization's clothes. REGIME: multi-warp-per-head recurrence kernels where a per-(token, head) scalar gate feeds every column-warp; long token loops. ANTI-REGIME: single-warp shapes (no redundancy to hoist); raw-gate consumers below the activation threshold; gates that depend on per-column state (not per-(token, head) constants). KINSHIP (do not double-count): hoist-group-invariant-scale-out-of-word-loop (gpu_01) hoists loop-invariant scales WITHIN one loop — THIS hoists cross-WARP invariant transcendentals into a separate pass with a template pairing; the static_assert pairing is the new face vs every hoist-family member. NOVEL (grep 'G_PRECOMPUTED|gate.{0,20}precompute|precompute.{0,20}gate|column.?warp.{0,25}redundan' over both corpora at claim: ZERO hits). NotBenchable here (no CUDA host in this corpus's served paths; the thresholds are source-stated — CPU-testable: pass output == in-kernel activation bitwise, with exactly-once evaluation counted). Source: Layr-Labs/cudafast-bonsai2-9b-engine @ 36c9536, MIT — llama.cpp/ggml/src/ggml-cuda/gated_delta_net.cu:229-242 + gated_delta_net_kernel.cuh:30-43, 233, 357, 511. Batch 251 / Plan 255 / Research 284.".to_string(),
            ref_shape: "// naive: every column-warp re-derives the same per-(token, head)\n// gates inside the recurrence — four warps, four identical\n// transcendental chains per token.\n\nfn gate_activation_in_kernel(g: f32, beta: f32, raw_a: f32, dt_bias: f32) -> (f32, f32) {\n    // the RAW branch: softplus with the overflow cut, then sigmoid\n    let x = g + dt_bias;\n    let g0 = raw_a * if x > 20.0 { x } else { (1.0 + x.exp()).ln() };\n    let g_val = g0.exp();\n    let beta_val = 1.0 / (1.0 + (-beta).exp());\n    (g_val, beta_val)\n}\n\n// n_column_warps evaluations of the SAME gate per token\nfn step_naive(gates: &[(f32, f32)], n_column_warps: usize, raw_a: f32, dt_bias: f32, evals: &mut usize) -> Vec<f32> {\n    gates\n        .iter()\n        .map(|&(g, beta)| {\n            let mut acc = 0.0f32;\n            for _ in 0..n_column_warps {\n                let (g_val, _) = gate_activation_in_kernel(g, beta, raw_a, dt_bias);\n                *evals += 1; // every column-warp recomputes the same gate\n                acc += g_val;\n            }\n            acc\n        })\n        .collect()\n}\n".to_string(),
            opt_pattern: "// optimized: one precompute pass activates every (token, head)\n// gate ONCE with the kernel's expressions; the kernel reads the\n// precomputed values behind a G_PRECOMPUTED template flag, and the\n// RAW/G_PRECOMPUTED pair is a compile error (double activation\n// cannot compile).\n\nfn gate_activation_in_kernel(g: f32, beta: f32, raw_a: f32, dt_bias: f32) -> (f32, f32) {\n    let x = g + dt_bias;\n    let g0 = raw_a * if x > 20.0 { x } else { (1.0 + x.exp()).ln() };\n    (g0.exp(), 1.0 / (1.0 + (-beta).exp()))\n}\n\n// static_assert(!(RAW && G_PRECOMPUTED)) — the kernel template's law\nconst fn pairing_law(raw: bool, g_pre: bool) -> bool {\n    !(raw && g_pre)\n}\nconst _: () = assert!(pairing_law(false, true) && pairing_law(true, false) && pairing_law(false, false));\n\nfn precompute_pass(gates: &[(f32, f32)], raw_a: f32, dt_bias: f32, evals: &mut usize) -> Vec<(f32, f32)> {\n    let mut out = Vec::with_capacity(gates.len());\n    for &(g, beta) in gates {\n        *evals += 1; // once per (token, head), not once per column-warp\n        out.push(gate_activation_in_kernel(g, beta, raw_a, dt_bias)); // the SAME expressions\n    }\n    out\n}\n\n// the incumbent, as the oracle: every column-warp re-derives the gate\nfn step_naive(gates: &[(f32, f32)], n_column_warps: usize, raw_a: f32, dt_bias: f32, evals: &mut usize) -> Vec<f32> {\n    let mut out = Vec::with_capacity(gates.len());\n    for &(g, beta) in gates {\n        let mut acc = 0.0f32;\n        for _ in 0..n_column_warps {\n            let (g_val, _) = gate_activation_in_kernel(g, beta, raw_a, dt_bias);\n            *evals += 1; // every column-warp recomputes the same gate\n            acc += g_val;\n        }\n        out.push(acc);\n    }\n    out\n}\n\n#[test]\nfn the_pass_activates_once_with_the_kernels_expressions() {\n    // one gate past the softplus overflow cut (x > 20)\n    let gates = [(0.3f32, -1.2), (25.0, 0.5), (-30.0, 2.0)];\n    let (raw_a, dt_bias) = (1.5f32, 0.1);\n    let mut evals = 0usize;\n\n    let _ = step_naive(&gates, 4, raw_a, dt_bias, &mut evals);\n    assert_eq!(evals, 12, \"four column-warps recomputed every gate\");\n\n    evals = 0;\n    let pre = precompute_pass(&gates, raw_a, dt_bias, &mut evals);\n    assert_eq!(evals, 3, \"the pass activates each gate exactly once\");\n    for (i, &(g, beta)) in gates.iter().enumerate() {\n        let (in_kernel, _) = gate_activation_in_kernel(g, beta, raw_a, dt_bias);\n        assert_eq!(pre[i].0.to_bits(), in_kernel.to_bits(), \"the pass IS the kernel's expression, bit for bit\");\n    }\n\n    // the pairing law: RAW && G_PRECOMPUTED must not compile\n    assert!(!pairing_law(true, true), \"static_assert(!(RAW && G_PRECOMPUTED))\");\n\n    // the overflow branch is reproduced verbatim: x > 20 takes raw x\n    let via_pre = precompute_pass(&[(1.0e30, 0.0)], 1.0, 0.0, &mut evals);\n    assert_eq!(via_pre[0].0.to_bits(), f32::INFINITY.to_bits(), \"1.0e30 > 20 -> exp(1.0e30) = inf, the branch cut preserved\");\n}\n".to_string(),
        },
        // ── D: exact top-k for wide rows — sorted per-chunk partial lists
        // merged head-only; only the winner's list ever advances. ──
        KernelRule {
            rule_id: "topk-chunk-partial-lists-head-only-kway-merge".to_string(),
            gpu_concept: "MECHANISM (exact top-k for wide rows; category D — selection/two-pass dispatch): two exact passes replace a whole-row sort — verbatim: 'Pass 1 splits every row into chunks and writes the k best packed values of each chunk in descending order. Pass 2 merges the chunk lists (one warp when there are at most 32 of them, a block reduction otherwise) and writes the column indices in descending order.' (top-k-select.cuh:14-17). Exactness rests on the packed-key total order: 'The result is the same as taking the first k entries of the stable descending cub radix sort used by the argsort fallback: keys are ordered by cub's float bit twiddle, -0.0 is treated as +0.0, and equal keys keep ascending column order.' with 'Real keys are unique (the low word holds the column) and nonzero; 0 is padding.' (top-k-select.cuh:6-12) and the pack 'return ((uint64_t) ord << 32) | (uint64_t) (~(uint32_t) col);     // ties: lower column first' (top-k-select.cuh:38). THE MERGE IS THE RULE: the warp variant gives each lane ONE list — 'grid (nrows), 32 threads, nchunks <= TOPK_SELECT_MERGE_WARP: lane l owns chunk list l (descending, k entries). Only a list head can be the next winner, and only the winning list advances: an exact k-way merge.' (top-k-select.cuh:215-216) — each round is one warp max reduction over the heads, and the winner's holder alone advances ('if (r + 1 < k && head == winner) {' / '++pos;' / 'head = pos < k ? p[lane * k + pos] : 0;' — top-k-select.cuh:232-234): no list is ever re-scanned. The block variant keeps the incremental discipline at REGISTER granularity — 'Only the thread holding the (unique) winner needs a new maximum; every other thread's maximum is still its largest key below the winner. Several threads whose maximum is padding all stay at 0.' (top-k-select.cuh:203-204) — the per-round full re-scan ('if ((r == 0 || c < prev) && c > best) {' — top-k-select.cuh:255) is bounded by the previous winner and feeds only the winner-holder's rebuild. DECISION CONTENT: (a) split a wide-row top-k into per-chunk partial lists kept SORTED DESCENDING so the merge reads only heads — a k-way merge over sorted lists never re-scans a drained list; (b) one owner per list, one max-reduction per round, ONE list advances — the winner-holder's cursor is the only mutable state; (c) the block variant keeps the incremental law at register granularity: only the winner's holder rebuilds its maximum, everyone else's cached maximum stays valid because keys are UNIQUE and below the winner; (d) exactness comes from the packed-key total order (float twiddle + complemented column for deterministic ties + 0 as below-everything padding), never from approximate thresholds. REGIME: wide rows (vocab-class, hundreds of thousands of columns) with small k (<= 32) selected per row, chunked partial lists feeding a merge. ANTI-REGIME: k large relative to the chunk (lists k deep — register/scratch cost grows); few candidates (a full sort wins); DUPLICATE real keys (the winner-holder rescan requires uniqueness); streaming selection with unbounded survivor counts. KINSHIP (do not double-count): warp-bitonic-topk-merge-shuffle (gpu_48) merges per-LANE bitonic-sorted lists via butterfly exchange in registers — THIS merges per-CHUNK PERSISTED lists via head-only advance (the source's warp max is the same reduce primitive family, a different merge topology); register-width-topk-falls-back-to-tiled-radix-select (gpu_64) and order-stable-topk-via-index-sort (gpu_03) own sort/radix shapes. NOVEL (grep 'k.?way.?merge|list.?head.{0,25}(winner|advance)|head.?only.{0,20}merge|chunk.{0,15}partial.{0,15}list' over both corpora at claim: the 'head only' hits are vocab-head dispatch and a 'warp head merge' phrase — different axes; ZERO owners of the head-only k-way merge). NotBenchable here (no CUDA host in this corpus's served paths — CPU-testable exact merge oracle: the merge equals a full sort's top-k including tie order). Source: Layr-Labs/cudafast-bonsai2-9b-engine @ 36c9536, MIT — llama.cpp/ggml/src/ggml-cuda/top-k-select.cuh:3-39, 198-237, 250-263. Batch 251 / Plan 255 / Research 284.".to_string(),
            ref_shape: "// naive: top-k by sorting the whole row — exact but O(n log n)\n// over a vocab-class row for a handful of outputs.\n\nfn topk_full_sort(row: &[f32], k: usize) -> Vec<usize> {\n    let mut idx: Vec<usize> = (0..row.len()).collect();\n    // descending by value, ties by lower column\n    idx.sort_by(|&i, &j| row[j].total_cmp(&row[i]).then(i.cmp(&j)));\n    idx.truncate(k);\n    idx\n}\n".to_string(),
            opt_pattern: "// optimized: two exact passes — per-chunk k best DESCENDING\n// (packed keys: float twiddle high word, complemented column low\n// word, 0 pads), then a merge where ONLY a list head can win and\n// only the winner's list advances. No list is ever re-scanned.\n\nfn pack(v: f32, col: usize) -> u64 {\n    let mut u = v.to_bits();\n    if u == 0x8000_0000 {\n        u = 0; // -0.0 sorts as +0.0\n    }\n    let ord = if u & 0x8000_0000 != 0 { !u } else { u | 0x8000_0000 }; // the float twiddle\n    ((ord as u64) << 32) | (!(col as u32) as u64) // ties: lower column first\n}\n\nfn chunk_partials(row: &[f32], chunk: usize, k: usize) -> Vec<Vec<u64>> {\n    row.chunks(chunk)\n        .enumerate()\n        .map(|(ci, c)| {\n            let mut keys: Vec<u64> = c.iter().enumerate().map(|(i, v)| pack(*v, ci * chunk + i)).collect();\n            keys.sort_unstable();\n            keys.reverse(); // descending\n            keys.truncate(k);\n            keys.resize(k, 0); // 0 pads a short chunk: ranks below every real key\n            keys\n        })\n        .collect()\n}\n\nfn merge_heads(lists: &[Vec<u64>], k: usize) -> Vec<usize> {\n    let mut pos = vec![0usize; lists.len()];\n    let mut heads: Vec<u64> = lists.iter().map(|l| l[0]).collect();\n    let mut out = Vec::with_capacity(k);\n    for _ in 0..k {\n        let winner = *heads.iter().max().unwrap(); // the warp/block max reduction\n        out.push((!(winner as u32)) as usize); // the column rides the low word\n        for (l, h) in heads.iter_mut().enumerate() {\n            if *h == winner {\n                // only the winning list advances\n                pos[l] += 1;\n                *h = if pos[l] < k { lists[l][pos[l]] } else { 0 };\n                break; // keys are unique: exactly one holder\n            }\n        }\n    }\n    out\n}\n\nfn topk_two_pass(row: &[f32], k: usize) -> Vec<usize> {\n    merge_heads(&chunk_partials(row, 64, k), k)\n}\n\n// the incumbent, as the oracle: a whole-row sort\nfn topk_full_sort(row: &[f32], k: usize) -> Vec<usize> {\n    let mut idx: Vec<usize> = (0..row.len()).collect();\n    // descending by value, ties by lower column\n    idx.sort_by(|&i, &j| row[j].total_cmp(&row[i]).then(i.cmp(&j)));\n    idx.truncate(k);\n    idx\n}\n\n#[test]\nfn the_head_only_merge_equals_a_full_sort_exactly() {\n    // heavy ties (mod 97) exercise the packed-key tie order\n    let row: Vec<f32> = (0..1000)\n        .map(|i| ((i as u64 * 2654435761 % 97) as i32 - 48) as f32)\n        .collect();\n    let k = 16;\n    assert_eq!(topk_two_pass(&row, k), topk_full_sort(&row, k), \"the two-pass merge must equal the full sort exactly, ties included\");\n\n    // short chunk tails pad with 0 and still rank below every real key\n    let odd: Vec<f32> = (0..70).map(|i| (i % 13) as f32).collect();\n    assert_eq!(topk_two_pass(&odd, 5), topk_full_sort(&odd, 5));\n\n    // uniqueness: two equal values at different columns pack differently\n    assert_ne!(pack(1.0, 3), pack(1.0, 7), \"the column in the low word keeps keys unique\");\n}\n".to_string(),
        },
        // ── A: clear traffic — track what a request could have written,
        // clear only that, and make capture-time marks survive every
        // clear because a graph replay rewrites them. ──
        KernelRule {
            rule_id: "per-request-dirty-range-clear-graph-capture-sticky-marks".to_string(),
            gpu_concept: "MECHANISM (per-request state clear; category A — memory access/clear-traffic): the incumbent zeroes whole memory buffers at every request clear — the backend instead tracks the byte ranges the previous request can have written and zeroes only those (verbatim: 'llama zeroes its whole memory buffers at every clear (each request): the KV cache and the recurrent-state buffer. To zero only what the previous request can have written, llama tracks the KV cells it assigned and asks this backend for the bytes written into the tensors it registers for write tracking (the recurrent S caches), then zeroes those ranges (ggml_backend_cuda_clear_ranges, asynchronous like the whole-buffer clear). Everything else in the buffer was zero after the previous clear and has not been written since.' — state-clear.cuh:5-9). Tracking is row-granular with a deliberate superset: 'Tracking granularity: rows of GGML_CUDA_DIRTY_ROW bytes from the start of the tensor; per row the length of the dirty prefix (a write [a, b) inside a row marks the prefix up to b, a superset).' ('#define GGML_CUDA_DIRTY_ROW (64*1024)' — :26). Writer coverage is THREE classes, and completeness is the safety property: 'every graph node whose output lies in a tracked tensor, marked before the graph is evaluated (ggml_cuda_dirty_mark_graph) and again when ggml_cuda_compute_forward runs it;' / 'the GATED_DELTA_NET kernel that writes its state snapshots straight into the cache (the CPY it absorbs is not marked in the pre-pass): its exact footprint (gated_delta_net.cu);' / 'host writes through the buffer interface (set / memset / cpy tensor).' (:13-17) — the kernel's own footprint is derived from the SAME predicates as its dispatch (gated_delta_net.cu:195-198: 'GB10 per-request state clear (C68): the cache bytes this launch writes (state-clear.cuh), from the same predicates as the kernels. Per (seq, head) row of S_v*S_v floats: lazy: rollback slots 0 (final state) and 1 (window base) in full, slots 2 .. 1 + grid_z the record (header + W tokens); eager: slots 0 .. min(T, K) - 1 in full; K == 1: slot 0.') because the CPY it absorbs is invisible to the graph pre-pass. THE DECISION-HEAVY HALF: 'Marks made while a stream is being captured into a CUDA graph also go to a sticky set that no clear resets: the graph may be replayed later without any host-side evaluation, and each replay rewrites that footprint.' (:18-19) — a captured graph replays with no host evaluation, so capture-time marks must survive every clear or post-clear reasoning about what can be non-zero is wrong. DECISION CONTENT: (a) a whole-buffer clear per request is paid in bytes the request never touched — track write ranges at ROW granularity (64 KiB) with a dirty-PREFIX superset and clear only those; (b) writer coverage must be COMPLETE over three classes — graph nodes (pre-pass + evaluation), kernels whose writes the pre-pass cannot see (absorbed CPYs -> the kernel's own footprint), and host writes — one missed class silently reads stale garbage as zeros; (c) marks made DURING stream capture are STICKY across clears: a captured graph replays without host evaluation and rewrites its footprint every replay; (d) the kernel-side footprint derives from the SAME predicates as the dispatch (lazy vs eager slots, grid_z, W) — one predicate source, two consumers, never a parallel estimate. REGIME: persistent state caches cleared per request (KV + recurrent S) on backends that can track host/device write ranges; graph-replaying serving loops. ANTI-REGIME: buffers fully rewritten every step (tracking overhead, no elision); writers that cannot be enumerated (third-party kernels/DMA outside the tracker); capture-free loops with no sticky-set problem (plain tracking suffices). KINSHIP (do not double-count): skip-unchanged-writes-via-dirty-encoding (gpu_07) elides KERNEL WRITES via in-encoding dirty bits — THIS is host-side RANGE TRACKING eliding CLEARS plus the sticky capture set; cuda-graph-scalar-via-device-pointer (gpu_01) and per-sequence-lazy-graph-capture-on-own-buffers (gpu_102) own graph-capture arg/buffer problems — THIS owns the clear-tracking interaction with capture. NOVEL (grep 'dirty.?row|sticky.{0,12}set|write.?range.{0,20}track|clear.{0,15}range|graph.?capture.{0,25}(mark|sticky)' over both corpora at claim: the graph-capture hits are the scalar-arg and lazy-capture rules — different concerns; ZERO owners of dirty-range clears + sticky marks). NotBenchable here (no CUDA host in this corpus's served paths; the elided clear bytes are count-stated — CPU-testable: the tracking model, clears resetting non-sticky marks and replays not). Source: Layr-Labs/cudafast-bonsai2-9b-engine @ 36c9536, MIT — llama.cpp/ggml/src/ggml-cuda/state-clear.cuh:3-36 + gated_delta_net.cu:195-222. Batch 251 / Plan 255 / Research 284.".to_string(),
            ref_shape: "// naive: every request clear zeroes the whole buffer.\nfn clear_all(buf: &mut [u8]) {\n    buf.fill(0);\n}\n\n// a writer the tracker cannot see: an absorbed write that lands in\n// the buffer without any graph node marking it\nfn absorbed_write_naive(buf: &mut [u8], at: usize, payload: &[u8]) {\n    buf[at..at + payload.len()].copy_from_slice(payload);\n}\n".to_string(),
            opt_pattern: "// optimized: row-granular dirty-prefix tracking (a write [a, b)\n// marks the prefix up to b — a deliberate superset), three writer\n// classes, and a STICKY set for marks made during stream capture\n// that no clear resets — a replayed graph rewrites its footprint\n// with no host evaluation.\n\nconst ROW: usize = 64; // GGML_CUDA_DIRTY_ROW, scaled down for the mirror\n\n#[derive(Default)]\nstruct DirtyTracker {\n    dirty: Vec<bool>,  // per row, reset by a clear\n    sticky: Vec<bool>, // per row, made during capture, never reset\n}\n\nimpl DirtyTracker {\n    fn mark(&mut self, at: usize, len: usize, capture: bool) {\n        let end = at + len;\n        let mut r = at / ROW;\n        while r * ROW < end {\n            self.dirty[r] = true;\n            if capture {\n                self.sticky[r] = true; // the sticky set\n            }\n            r += 1;\n        }\n    }\n\n    /// zeroes the ranges a writer could have touched; returns the rows\n    /// zeroed. Non-marked rows were zero after the previous clear.\n    fn clear(&mut self, buf: &mut [u8]) -> Vec<usize> {\n        let mut zeroed = Vec::new();\n        for (r, cell) in buf.chunks_mut(ROW).enumerate() {\n            if self.dirty[r] || self.sticky[r] {\n                cell.fill(0);\n                zeroed.push(r);\n            }\n            self.dirty[r] = false; // the sticky set is NOT reset\n        }\n        zeroed\n    }\n}\n\n#[test]\nfn the_sticky_set_survives_clears_and_the_prefix_is_a_superset() {\n    let mut buf = vec![0u8; 16 * ROW];\n    let mut t = DirtyTracker { dirty: vec![false; 16], sticky: vec![false; 16] };\n\n    // a host write mid-row 1: the PREFIX up to b marks (superset)\n    buf[ROW + 10] = 0xFF;\n    t.mark(ROW + 10, 1, false);\n    assert_eq!(t.clear(&mut buf), vec![1], \"only the dirty row is zeroed\");\n    assert_eq!(buf[ROW + 10], 0);\n\n    // a capture-time write into row 2: the mark is sticky\n    buf[2 * ROW] = 0xFF;\n    t.mark(2 * ROW, 1, true);\n    assert_eq!(t.clear(&mut buf), vec![2], \"the capture footprint zeroes like any dirty row\");\n    assert!(t.sticky[2], \"the sticky set survives the clear\");\n\n    // a replay (a capture mark again, no host evaluation) then a clear\n    // with no other writers: the sticky row still clears, nothing else does\n    t.mark(2 * ROW + 3, 1, true); // the graph's replay rewrites its footprint\n    buf[2 * ROW + 3] = 0xFF;\n    assert_eq!(t.clear(&mut buf), vec![2], \"the sticky row clears again; clean rows do not\");\n    assert_eq!(buf[ROW + 10], 0, \"previously cleared rows stay zero\");\n}\n".to_string(),
        },
        // ── A: staging shape — a ubatch whose whole window fits shared
        // memory should commit once and wait once, with per-token gates
        // activated once per lane and broadcast per step. ──
        KernelRule {
            rule_id: "verify-ubatch-full-prestage-lane-token-gate-broadcast".to_string(),
            gpu_concept: "MECHANISM (short-ubatch staging; category A — memory access/staging): for verify-sized ubatches (8-16 tokens, the MTP draft-depth band) the staged ring (a few tokens per stage, commit + wait per stage) is the wrong shape — the whole window fits one shared allocation. The L8V arm stages ALL token inputs but q UP FRONT: 'GB10 verify-sized ubatches (n_tokens <= GDN_L8V_MAX_TOKENS): gated_delta_net_l8_cuda with all token inputs but q staged in shared memory before the recurrence and the gates activated once per token (by lane t), so a step waits on no global load of k, v, g or beta.' (kernel.cuh:802-804) — 'All n_tokens (<= GDN_L8V_MAX_TOKENS) tokens' k rows (in the order lane n reads them: [r][n][m]), the block's 16 v columns, g and beta are copied to shared memory up front (cp.async, overlapping the state load).' (kernel.cuh:841-842) — ONE cp.async commit overlapping the state load, ONE wait, and the recurrence reads nothing from global for k/v/g/beta. Per-token gate activation is DISTRIBUTED: 'the gates of token t, activated by lane t with the main loop's expressions, are broadcast in its step' (kernel.cuh:938) — 'if (lane < n_tokens) {' / 'beta_lane = stage[lane][S_v + 17];' (kernel.cuh:940-941) evaluates each token's trans%c3%a9ndentals exactly once per BLOCK (not per column-warp), and each step broadcasts via 'const float beta_val = __shfl_sync(0xffffffff, beta_lane, t, 32);' / 'const float g_val    = __shfl_sync(0xffffffff, g_lane, t, 32);' (kernel.cuh:991-992). The band is measured and three-armed: '#define GDN_L8V_MIN_TOKENS 8   // gated_delta_net_l8v_cuda: ubatches of GDN_L8V_MIN_TOKENS ..' / '#define GDN_L8V_MAX_TOKENS 16  // .. GDN_L8V_MAX_TOKENS tokens (the 16-row verify; at most 32)' (kernel.cuh:512-513) — below 8 the eager base kernel, 8-16 the full-prestage arm, >= 17 the staged-ring arm. The broadcast's arithmetic bound is n_tokens <= 32: lane t must exist for every token. Lazy-verify additionally requires the window to cover every token: 'n_tokens >= GDN_L8V_MIN_TOKENS && n_tokens <= GDN_L8V_MAX_TOKENS && (!lazy_eff || n_tokens <= K)) {' (gated_delta_net.cu:64-65) — so slot 0 needs no final-state store and is rebuilt purely by replay. DECISION CONTENT: (a) a ubatch whose whole token window fits one shared allocation should commit ONE async-copy group for everything-but-q and wait once — the ring's commit/wait cadence is pure overhead at 8-16 tokens; (b) distribute per-token transcendental work across lanes (lane t owns token t) and broadcast by shuffle — each activation evaluated exactly once, with the SAME expressions as the in-kernel path (bit-identity preserved); (c) the broadcast's arithmetic bound is n_tokens <= warp width (32) — the lane-t mapping must exist for every token; (d) dispatch on measured band boundaries (8 / 16 / 17) with the eager base below the band and the ring above it; (e) lazy-verify requires the window to cover every token (n_tokens <= K) so slot 0 needs no final-state store. REGIME: verify/draft-depth ubatches (8-16 tokens) over a recurrence whose per-token inputs fit shared memory; any short-ubatch regime where a pipeline's stage depth exceeds the token count. ANTI-REGIME: long ubatches (the ring's overlap wins — shared memory cannot hold all tokens); n_tokens > 32 (the lane-t broadcast has no lane); token windows too large for the shared allocation. KINSHIP (do not double-count): cpasync-multistage-tile-pipeline (gpu_09) is the OPPOSITE end — multi-stage ring vs single-commit full prestage; gate-activation-precompute-pass (this batch) owns the CROSS-WARP separate-pass form of the same redundancy — THIS owns the lane-distributed broadcast inside one block; lazy-rollback-journaled-window (this batch) owns the NOFINAL mark this arm sets. NOVEL (grep 'full.?prestage|verify.?sized.{0,25}ubatch|lane.{0,4}t.{0,30}broadcast|gates.{0,25}broadcast' over both corpora at claim: ZERO owners). NotBenchable here (no CUDA host in this corpus's served paths; CPU-modelable — the broadcast is exactly-once evaluation and the dispatch bands are source-stated constants). Source: Layr-Labs/cudafast-bonsai2-9b-engine @ 36c9536, MIT — llama.cpp/ggml/src/ggml-cuda/gated_delta_net_kernel.cuh:507-513, 802-870, 938-951, 991-992 + gated_delta_net.cu:61-80. Batch 251 / Plan 255 / Research 284.".to_string(),
            ref_shape: "// naive: a short verify ubatch runs the pipelined ring — stages of\n// a few tokens, commit + wait per stage — and every column-warp\n// recomputes the per-token gates.\nconst STAGE: usize = 4;\n\nfn ring_stages(n_tokens: usize) -> usize {\n    (n_tokens + STAGE - 1) / STAGE // commit/wait cadence per stage\n}\n\nfn gate_per_warp(g: f32, warps: usize, evals: &mut usize) -> f32 {\n    let mut acc = 0.0f32;\n    for _ in 0..warps {\n        *evals += 1;\n        acc += g.exp(); // every column-warp recomputes the same gate\n    }\n    acc\n}\n".to_string(),
            opt_pattern: "// optimized: the whole window fits one shared allocation — stage\n// ALL token inputs but q in ONE async-copy commit overlapping the\n// state load, wait once, then run the recurrence off shared memory;\n// per-token gates are activated by lane t ONCE and broadcast per\n// step with a shuffle.\n\nfn dispatch_arm(n_tokens: usize) -> &'static str {\n    match n_tokens {\n        0..=7 => \"eager\",              // below the band\n        8..=16 => \"l8v-full-prestage\", // the verify band: one commit, one wait\n        _ => \"l8-ring\",                // prefill: the staged ring\n    }\n}\n\nfn full_prestage_commits(n_tokens: usize) -> usize {\n    // the broadcast's arithmetic bound is n_tokens <= 32 (lane t must\n    // exist); the band itself is 8..=16\n    if (8..=16).contains(&n_tokens) && n_tokens <= 32 {\n        1\n    } else {\n        (n_tokens + 4 - 1) / 4 // the ring's cadence\n    }\n}\n\n/// lazy-verify additionally requires the window to cover every token:\n/// slot 0 is then rebuilt purely by replay (the NOFINAL face)\nfn lazy_verify_ok(n_tokens: usize, k: usize) -> bool {\n    n_tokens <= k\n}\n\n/// lane t activates token t once; each step reads lane t's value\nfn lane_broadcast_gates(gates: &[f32], evals: &mut usize) -> Vec<f32> {\n    let mut lane_activated = vec![0.0f32; 32];\n    for (t, g) in gates.iter().enumerate() {\n        *evals += 1; // exactly once per token, not per column-warp\n        lane_activated[t] = g.exp(); // the main loop's expression\n    }\n    lane_activated\n}\n\nfn step_broadcast(lane_activated: &[f32], t: usize) -> f32 {\n    lane_activated[t] // __shfl_sync(mask, g_lane, t, 32): every lane reads lane t\n}\n\n#[test]\nfn the_full_prestage_broadcast_evaluates_each_gate_once() {\n    let gates: Vec<f32> = (1..=12).map(|i| 0.1 * i as f32).collect();\n    let mut evals = 0usize;\n    let activated = lane_broadcast_gates(&gates, &mut evals);\n    assert_eq!(evals, 12, \"lane t activated token t — once per token, not per warp\");\n    for (t, g) in gates.iter().enumerate() {\n        assert_eq!(step_broadcast(&activated, t).to_bits(), g.exp().to_bits(), \"the broadcast value IS the local activation\");\n    }\n\n    // the three-arm dispatch on the measured band boundaries\n    assert_eq!(dispatch_arm(7), \"eager\", \"< 8: the eager base kernel\");\n    assert_eq!(dispatch_arm(12), \"l8v-full-prestage\", \"8..16: the full-prestage arm\");\n    assert_eq!(dispatch_arm(17), \"l8-ring\", \">= 17: the staged ring\");\n    assert_eq!(full_prestage_commits(12), 1, \"one commit, one wait for the whole window\");\n    assert_eq!(full_prestage_commits(64), 16, \"past the band the ring's cadence returns\");\n\n    // the lazy-verify window requirement\n    assert!(lazy_verify_ok(12, 16));\n    assert!(!lazy_verify_ok(12, 8), \"n_tokens > K: slot 0 would need a final-state store\");\n}\n".to_string(),
        },
        // ── L: the layout constant — one host+device derivation over the
        // COMPILED arch, so a runtime cc above the build never disagrees
        // with the binary that actually runs. ──
        KernelRule {
            rule_id: "host-dispatch-predicate-mirrors-kernel-compiled-arch".to_string(),
            gpu_concept: "MECHANISM (host/device layout agreement; category L — layout/config-key contract): a kernel resolves a layout constant from the COMPILE-TIME arch while the host launch geometry needs the SAME value from the runtime cc, which may EXCEED the highest compiled arch. The fix is one __host__ __device__ function as the single source — verbatim: 'Host and device must agree on columns/warp. Kernel uses __CUDA_ARCH__; host uses ggml_cuda_highest_compiled_arch(cc). NVIDIA Ampere+ and S_v==128 and !KDA -> 4; HIP/MUSA stay 1.' followed by 'static constexpr __host__ __device__ int gdn_cols_per_warp(int arch, int S_v, bool KDA) {' (kernel.cuh:7-8). The kernel side: '#if defined(__CUDA_ARCH__)' / 'constexpr int cols_per_warp = gdn_cols_per_warp(__CUDA_ARCH__, S_v, KDA);' / '#else' / 'constexpr int cols_per_warp = 1; // host pass only; never executed' (kernel.cuh:271-274) — the non-device arm returns the neutral 1 with the never-executed comment, a documented fallback, not a load-bearing value. The host side: 'Same predicate as the kernel, fed the arch compiled for this cc.' / 'const int cols_per_warp = GGML_CUDA_CC_IS_NVIDIA(cc) ? gdn_cols_per_warp(ggml_cuda_highest_compiled_arch(cc), S_v, KDA) : 1;' (gated_delta_net.cu:24-25) — highest_compiled_arch CLAMPS the runtime cc to what was actually built, which is exactly the derivation the shipped kernel binary contains; and the SECOND consumer (the dirty-mark footprint estimator) re-derives through the same function: 'const int     cpw        = GGML_CUDA_CC_IS_NVIDIA(cc_fp) ? gdn_cols_per_warp(ggml_cuda_highest_compiled_arch(cc_fp), S_v, kda) : 1;' (gated_delta_net.cu:201). The defect class is the host-side TRANSCRIPTION of the predicate: a copy that drifts (loses the Ampere gate, gains a HIP arm) sizes the grid for a different lane map than the launched kernel uses — silent corruption, no error. DECISION CONTENT: (a) a layout constant the kernel derives from the compile-time arch must be re-derivable on the host from the runtime cc — and the derivation must agree even when runtime cc > highest compiled arch, because highest_compiled_arch clamps to what the running binary contains; (b) ONE __host__ __device__ function is the single source — a host-side transcription of the predicate is the defect (grid geometry vs kernel lane map disagree -> wrong columns per warp, silent corruption); (c) every consumer (launch geometry, dirty-mark footprint, kernel body) re-derives through the function — 'from the same predicates as the kernels' applied to layout constants; (d) the non-device compilation arm returns the neutral value WITH a never-executed comment — the fallback is documented, never silently load-bearing. REGIME: kernels whose work partition depends on the compiled arch (lane maps, register ladders) launched from hosts that also size grids or derive footprints from the runtime device. ANTI-REGIME: constants identical across arches (no agreement problem); host-only constants the kernel never reads; device-side autotune that measures instead of deriving (a different mechanism). KINSHIP (do not double-count): the host/device AGREEMENT contract behind occupancy-keyed-value-split-register-budget-ladder (gpu_94) and pipeline-thread-capacity-declared-by-launcher (gpu_101) — those own capacity/launch contracts declared by one side; THIS owns the arch-DERIVATION seam (compiled arch vs runtime cc) as the single-function fix. NOVEL (grep 'highest.?compiled.?arch|host.{0,5}device.{0,20}agree|__CUDA_ARCH__.{0,40}highest' over both corpora at claim: ZERO hits). NotBenchable here (pure logic — testable as the function itself: host(arch = highest_compiled_arch(cc)) == the device derivation for every cc below, at, and above the compiled arch). Source: Layr-Labs/cudafast-bonsai2-9b-engine @ 36c9536, MIT — llama.cpp/ggml/src/ggml-cuda/gated_delta_net_kernel.cuh:7-15, 271-275 + gated_delta_net.cu:24-25, 201. Batch 251 / Plan 255 / Research 284.".to_string(),
            ref_shape: "// naive: the host TRANSCRIBES the kernel's arch predicate — a\n// second copy that drifts (here it forgets the Ampere gate), so the\n// grid is sized for 4 columns/warp while the launched kernel (compiled\n// for an older arch) uses 1 — silent corruption.\n\nfn cols_per_warp_host_copy(s_v: i32, kda: bool) -> i32 {\n    if s_v == 128 && !kda { 4 } else { 1 } // the Ampere gate is LOST\n}\n\nfn grid_z_naive(s_v: i32, num_warps: i32, kda: bool) -> i32 {\n    let cpw = cols_per_warp_host_copy(s_v, kda);\n    (s_v + num_warps * cpw - 1) / (num_warps * cpw)\n}\n\n// the kernel's real derivation, compiled for a specific arch\nfn kernel_cols_per_warp(compiled_arch: i32, s_v: i32, kda: bool) -> i32 {\n    if compiled_arch >= 80 && s_v == 128 && !kda { 4 } else { 1 }\n}\n".to_string(),
            opt_pattern: "// optimized: ONE host+device function is the single source; the\n// kernel feeds __CUDA_ARCH__, the host feeds\n// highest_compiled_arch(cc) — the clamp to the COMPILED SET that\n// makes any runtime cc agree with the cubin that actually runs.\n\n/// the arches this build shipped SASS for\nconst COMPILED_ARCHES: [i32; 3] = [70, 80, 90];\n\nfn cols_per_warp(arch: i32, s_v: i32, kda: bool) -> i32 {\n    if arch >= 80 && s_v == 128 && !kda { 4 } else { 1 }\n}\n\n/// the host's only lawful input: the highest compiled arch <= cc —\n/// exactly the __CUDA_ARCH__ of the cubin the device will run\nfn highest_compiled_arch(cc: i32) -> i32 {\n    let mut best = 0;\n    for a in COMPILED_ARCHES {\n        if a <= cc && a > best {\n            best = a;\n        }\n    }\n    best\n}\n\nfn grid_z(s_v: i32, num_warps: i32, kda: bool, cc: i32) -> i32 {\n    let cpw = cols_per_warp(highest_compiled_arch(cc), s_v, kda); // the SAME fn as the kernel\n    (s_v + num_warps * cpw - 1) / (num_warps * cpw)\n}\n\n#[test]\nfn the_host_and_device_derivations_agree_at_every_runtime_cc() {\n    for cc in [70i32, 80, 86, 89, 90, 100, 120] {\n        // the device runs the highest compiled arch <= cc; its\n        // __CUDA_ARCH__ IS that arch, so the kernel computes\n        let device = cols_per_warp(highest_compiled_arch(cc), 128, false);\n        // the host re-derives through the SAME function, same input\n        let host = cols_per_warp(highest_compiled_arch(cc), 128, false);\n        assert_eq!(host, device, \"cc {cc}: host and device must agree on columns/warp\");\n        // and the grid geometry covers the state exactly, ceil semantics\n        let z = grid_z(128, 4, false, cc);\n        let covered = z * 4 * host;\n        assert!(covered >= 128 && covered - 4 * host < 128, \"cc {cc}: the grid covers 128 columns exactly\");\n    }\n    // a runtime cc ABOVE the compiled set clamps to the newest cubin —\n    // never to the (wrong) runtime cc\n    assert_eq!(highest_compiled_arch(120), 90);\n    // the naive transcription diverges the moment the predicate gains a\n    // gate the copy forgot (here: the Ampere floor at an arch-70 build)\n    assert_ne!(\n        cols_per_warp_host_copy(128, false),\n        cols_per_warp(70, 128, false),\n        \"the unshared copy diverges from the real derivation — the defect class\"\n    );\n}\n\nfn cols_per_warp_host_copy(s_v: i32, kda: bool) -> i32 {\n    if s_v == 128 && !kda { 4 } else { 1 }\n}\n".to_string(),
        },
    ]
}
